arguments.file_text:
@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore our departments and find the courses that shape your future.</p>
    <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
</div>

<section class="mt-5">
    <h2>Featured Courses</h2>
    <div class="row mt-3">
        @foreach (var course in _featuredCourses)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.Title</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.CourseCode · @course.Credits credits</h6>
                        <p class="card-text">@course.Description[..Math.Min(course.Description.Length, 120)]...</p>
                    </div>
                    <div class="card-footer">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section class="mt-5">
    <h2>Departments</h2>
    <div class="row mt-3">
        @foreach (var dept in _departments)
        {
            <div class="col-md-4 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text text-muted">@dept.Description</p>
                        <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetAllDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" class="form-control"
               placeholder="Search by title, code, or instructor..." value="@Search" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @_courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _courses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> _courses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetAllDepartments();
        _courses = CatalogService.SearchCourses(Search, DepartmentId);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p class="lead">Submit your enrollment request below. You will receive a confirmation once processed.</p>

<div class="row">
    <div class="col-md-8">
        <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" id="studentName" name="Model.StudentName" class="form-control"
                       value="@Model.StudentName" required />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" id="studentId" name="Model.StudentId" class="form-control"
                       value="@Model.StudentId" required pattern="[A-Za-z0-9]{6,12}"
                       title="6-12 alphanumeric characters" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select id="courseId" name="Model.CourseId" class="form-select" required>
                    <option value="">-- Select a Course --</option>
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                            @course.CourseCode — @course.Title
                        </option>
                    }
                </select>
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </form>
    </div>
</div>

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> _courses = new();

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollment(Model);
        Navigation.NavigateTo($"/enroll/confirmation?courseName={Uri.EscapeDataString(_courses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title ?? "Unknown")}");
    }

    [Inject] private NavigationManager Navigation { get; set; } = default!;
}

@page "/enroll/confirmation"

<PageTitle>Enrollment Submitted - University Course Catalog</PageTitle>

<div class="text-center mt-5">
    <h1 class="text-success">&#10003; Enrollment Request Submitted</h1>
    <p class="lead mt-3">Your enrollment request for <strong>@CourseName</strong> has been received.</p>
    <p>You will be notified by email once your request has been reviewed and processed.</p>
    <div class="mt-4">
        <a href="/courses" class="btn btn-primary me-2">Browse More Courses</a>
        <a href="/" class="btn btn-outline-secondary">Return Home</a>
    </div>
</div>

@code {
    [SupplyParameterFromQuery] public string? CourseName { get; set; }
}

